  const exitCode = await gateParsedProposal(
    {
      domain: gateDomain,
      input: analysis.input,
      inputId,
      proposal: analysis.proposal,
      // A live analysis is not a fixture; it has no fixture provenance.
      provenance: null,
      fixtureId: null,
      sourceId,
      policyPack: options.policyPack,
      receipt: options.receipt,
      signKey: options.signKey,
      receiptId: options.receiptId,
      format: options.format,
      mode: "live",
      model: analysis.model,
      note: `proposed live by ${provider.label} \xB7 model ${analysis.model}`,
      now: options.receiptCreatedAtUtc
    },
    console2
  );
  if (options.format === "pretty") {
    if (options.out) {
      console2.out(`  ${paint(console2.color, "dim", `proposal written to ${options.out}`)}`);
    }
    if (options.capture) {
      console2.out(
        `  ${paint(console2.color, "dim", `capture written to ${options.capture} (review before promoting it to a bundled fixture)`)}`
      );
    }
    if (options.out || options.capture) console2.out("");
  }
